#include <string>
#include <utility>

class Vehicle
{
public:
    Vehicle(std::string name, int wheels) : m_name{ std::move(name) }, m_wheels{ wheels } {}

    const std::string& name() const { return m_name; }
    int wheels() const { return m_wheels; }
    std::string describe() const { return m_name + " has " + std::to_string(m_wheels) + " wheels"; }

protected:
    void setWheels(int wheels) { m_wheels = wheels; }

private:
    std::string m_name{};
    int m_wheels{};
};

class Car : public Vehicle
{
public:
    Car(std::string name, int doors) : Vehicle{ std::move(name), 4 }, m_doors{ doors } {}
    int doors() const { return m_doors; }

private:
    int m_doors{};
};

class Motorbike : public Vehicle
{
public:
    explicit Motorbike(std::string name) : Vehicle{ std::move(name), 2 } {}

    bool hasSidecar() const { return m_sidecar; }
    void attachSidecar() { m_sidecar = true; setWheels(3); }

private:
    bool m_sidecar{ false };
};

unitTests:
template <typename T> concept CanSetWheels = requires(T t) { t.setWheels(1); };
static_assert(std::is_base_of_v<Vehicle, Car> && std::is_base_of_v<Vehicle, Motorbike>);
static_assert(!CanSetWheels<Car> && !CanSetWheels<Vehicle>, "setWheels should be protected, not public");

TEST("vehicle") { const Vehicle v{ "Cart", 2 }; CHECK_EQ(v.describe(), "Cart has 2 wheels"); }
TEST("car") { const Car c{ "Civic", 5 }; CHECK_EQ(c.wheels(), 4); CHECK_EQ(c.doors(), 5); CHECK_EQ(c.describe(), "Civic has 4 wheels"); }
TEST("motorbike and sidecar") { Motorbike m{ "Vespa" }; CHECK_EQ(m.wheels(), 2); CHECK(!m.hasSidecar()); m.attachSidecar(); CHECK(m.hasSidecar()); CHECK_EQ(m.describe(), "Vespa has 3 wheels"); }

